(window.webpackJsonp=window.webpackJsonp||[]).push([[105],{544:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“莫把自己放高位，只求与主，正人之前先正己，免得到头两手空。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家平安。我们一起来打开路加福音第6章。我们之前已经通过两次讲道，讲解了耶稣在拣选使徒后，对他的门徒所做的一段教导，被称为“平地宝训”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在第20~26节，他首先教导我们要做什么样的人。然后在第27~36节，他教导我们应该如何去对待别人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("今天我们继续来讲耶稣这段教导接下来的一部分。我们一起来读路加福音6:37~42节的内容。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们上次已经说了，在6:27~36节，耶稣是在以举重以明轻的方式，教导我们如何去对待别人，不仅是仇敌，而是所有人。就是要爱他们，并且出于爱而善待他们，也就是做出有利于他们的行动。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在那段经文中，他对门徒谈到要如何爱人时，列举了那些亏待他们、得罪他们的人作为例子。而诅咒、凌辱、抢夺、借钱却不还，这些行为本身，当然是错误的。由此耶稣继续地引申，开始涉及一个更具体的话题：对于那些有过犯人，我们应该如何爱他、善待他呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家一定见过，两个小朋友打架被大人拉开，然后互相指责，要追究谁是那个最先犯错的人。这种行为的心理动因，是要用对方的错误来合理化自己的行为。在我们长大以后，这种心理动因仍然存在。因此在与人相处时，尤其是在与人发生矛盾时，我们倾向于去寻找对方的过错，以证明自己的某种反应或行为是正常的、可以被理解的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("由于所有人都是罪人，因此只要你找，一定能找到对方有错的地方。那么当你判断清楚了对方确实有错，这时候我们应该做何反应、做什么行动，才是真正正常的、才是可以被神所认可的呢？当然，我们都知道原理，就是去爱他、善待他。那怎么才是爱他、善待他？这就是今天要讨论的主题。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为了便于大家记忆和把握，我把主在这里教导我们的内容总结成了一首打油诗。我先给大家念一遍：莫把自己放高位，只求与主心意同。正人之前先正己，免得到头两手空。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("下面我们就进入到经文当中。随着我对经文的讲解，大家也就自然知道这首打油诗的意思了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、莫把自己放高位")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("对于如何去爱、善待那些有过犯的人，主耶稣在第37节~38节，用了四个排比句，从否定、肯定两方面来教导我们。因此这四个排比句所表达的意思，是一以贯之，并且又互相补充的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("首先是否定的方面。耶稣提到你们“不要论断人”、“不要定人的罪”。我们在此可以清楚看到，在这上下文中，论断人和定人的罪是相联系的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("翻译为“论断”的这个词，希腊原文是κρίνω。这个词有多重含义，其中一个就是在法庭上进行审查和裁判。一个法官，端坐在法庭之上，桌上摆放着一本厚厚的律法，手中拿着法槌，对站在被告席中的人进行审问、并根据律法判定他的行为，这就是κρίνω。当判定被告违反了律法，就会定他的罪。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在庄严的法庭之上，法官是国家权力的直接象征。凭借这一权威，法官坐在高高的审判席上，俯瞰庭下。他审问、裁判、定罪的职责，不仅是权力的行使，更意味着一种超越于被审判者的优越地位。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以当有人看到一个有过犯的人，而去论断他、定他的罪的时候，意味着这个人首先就是把自己放在一个比对方高的地位上，这其实是他一种心态的反应，就是自己相对于对方有优越性。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你有这样的心态，那么你面对一个有过犯的人，你就会对他进行论断、定罪。主耶稣说，这也就意味着你必定不会爱他、善待他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家去自省、去观察，你就会发现，无论是你自己还是你身边的人，许多言行的背后，其实都蕴藏着这样的心态。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("有没有见过那些东家长西家短的人？你自己呢，有没有过在背后说人的坏话？有没有曾经面对别人的过犯，不屑地说，“他怎么会做这种事情”？有没有曾经委屈地、亦或是生气地抱怨，“我对他怎样怎样好，他居然怎样怎样对我”？甚至有没有有过这样的想法：“他这样对我，我绝不会原谅他”？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这些例子我们还可以举很多。你如果仔细去分析这些言行，你就会发现，其后面无非蕴藏的是同一种心理范式：把自己与对方进行比较，在比较中你认定自己比他强，然后就可以把你自己放在高位上来俯视他、审判他、论断他、定罪他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而主耶稣告诉我们说，你们不要这样。否则，你们自己会被论断、被定罪。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("被谁呢？当然是天上的神。只有他，才真正有权柄；只有他，才是真有优越性；只有他，才真正处高位；只有他，才真正有资格说，“我在殿中行审判，全地的人都当在我面前肃静！”（哈巴谷书2:20）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家一定要认识到，论断人、定人的罪，那是神的权柄，我们人没有资格做。谁如果越过这条线，你就是在僭越神的主权。主耶稣在这里严厉地警告我们，谁这样做，必被至高者论断、定罪。所以使徒们后来也反复提醒我们。在罗马书14:4，保罗就质问那些自觉优越、居高临下的人：“你是谁，竟论断别人的仆人呢？他或站住，或跌倒，自有他的主人在”；雅各也说，“设立律法和判断人的，只有一位，就是那能救人也能灭人的。你是谁，竟敢论断别人呢？”（雅各书4:12）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，我们要对神的主权有清醒的认识。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同时，我们对自己也要有清醒的认识。我们也确实没有什么资本来与别人进行比较，从而自觉优越，可以在对方面前居高临下。难道不是吗？难道一无所有、一无所能，不是每个人的客观情况吗？在物质上是如此，在灵性上是如此，在道德上也是如此。跟随耶稣的人是如此，不跟随耶稣的人也是如此。区别只在于你承认还是不承认。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你自己身上有什么可以依赖的东西，让你能在神面前称义吗？甚至你自己身上有什么可以依赖的东西，让你现在还配活着吗？如果不是神满有丰盛的慈爱和怜悯，公义的他看着你，恐怕只能对你说一句话：你现在就给我滚到地狱里面去吧。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以弟兄姐妹们，要看清这个事实。你绝没有任何地方比人强，绝没有！因为你一无所有、一无所能。只有在你拒绝承认这个事实，才会在与他人的比较中觉得自己“更优越”，才会试图站在高位，俯视别人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但如果你真的拒绝承认这个事实，你就有祸了！因为你不再承认自己是贫穷的人，反而自认富足，你就会开始从这种虚假的优越感中去获得安慰。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家静心想一想：另一个人行为如何，其实是他与神之间的事情。而你，为什么会忍不住在心里论断他、定他的罪？其实往往是因为，这样做能给你带来某种属灵上的虚假满足，让你在对比中觉得自己“更好”，从而产生心理上的快感。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但其实你什么也没有，就像他也什么也没有一样。你们是零比零，空对空。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这是主耶稣在6:37~38节中，从否定的方面教导我们，如何去爱那些有过犯的人，也就是我们的打油诗的第一句：莫把自己放高位。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、只求与主心意同")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来，我们来讲他从肯定方面的教导。主耶稣说你们要饶恕人、要给人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在上下文中，这里的“要给人”，不是泛泛地指给任何东西，而是和前面“饶恕”的意思相一贯。所以，主耶稣这里是指我们要毫不吝惜地把怜悯、恩慈、饶恕给与那些有过犯的人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来我来解释一下圣经中关于饶恕的观念。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我刚才说过在6:37翻译为“论断”的这个词κρίνω有多重的含义。除了法官行审判这个意思外，还有分辨、判断的意思。在这一层意思中，进行分辨、判断的人并不具有那种居高临下的地位，而只是一般地对事情做出辨别。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("进行辨别是每个人、每天都在做的事。你在决定采取某个行动之前，一定首先需要在头脑中判断这是正确的还是错误的；主耶稣在今天的经文中教导我们如何对待那有过犯之人，所以当然我们首先得来判断他是否有了过犯。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("既然要判断，那就需要有一个判断的标准。对于基督徒而言，这标准当然就是神的话。神说什么是对的什么就是对的，神说什么是错的什么就是错的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("因此一个有过犯的人，一定是得罪冒犯了神。但同时，他也可能直接得罪到我们。比如主耶稣在第6:28~29节讲到的那些咒诅、凌辱、抢夺你的人，他们既违背了神的律法，冒犯了神，但同时也得罪了你。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但冒犯神与得罪你，也可能并不同时发生。如果一个人咒诅、凌辱、抢夺的不是你，而是其他人，那么他仍然得罪了神，但并未对你个人造成直接的伤害。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当他人直接伤害到我们时，这种伤害往往会触动我们内心的私欲，带来情感与心灵上的痛苦。面对这样的处境，我们必须正视并处理自己里面的私欲问题。我们需要转向神，把自己投入他那深邃无垠的恩典之中，将自己沉浸在他那广阔无边的慈爱之内；为了神的缘故学习舍己，舍弃一切，摆脱私欲的缠累。向他呼喊：“神啊，我只要你，我的好处不在你以外！”通过对神的仰望和依靠，我们可以超越、消解那份因私欲未被满足而产生的痛楚。当你真正超越了这份痛苦、让它在你心中失去力量时，你也就放下了对方对你的伤害。在这时，你便在个人的层面上，真正饶恕了对方。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但这只是“饶恕”的一个层面。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("饶恕还有另一个层面。无论对方是否直接伤害我们个人，当他干犯了神的律法，这就冒犯了神。他的行为必然会触动神的愤怒，而我们作为神的子民，既然与他的心意相连，此时心里感到愤怒也是自然的、必然的。这就叫“义怒”，出于公义的愤怒。作为基督徒，如果我们面对罪恶却毫无这样的感受，那就需要去反思，你是否真的与主同心？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这时候，你应该如何来对待这个触动神的愤怒、也激起你的义怒的人呢？主耶稣说，你不是把你的怒火倾倒在他身上，而是要饶恕他、要给他怜悯、给他恩慈。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("区别于刚才个人层面的饶恕，这是公义层面的饶恕。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这公义层面的饶恕有三个特点，第一，它有部分是暂时的、属于今世的；第二，它另一部分则是彻底的、永恒的；第三，它始终带着对人的深切期盼。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣教导我们这样对待那些得罪神的人，是因为神自己就是这样做的。我们既然在“公义的愤怒”上与神同心，在“公义的饶恕”上，也当然应该与他同心。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么说神这“公义的饶恕”有部分是暂时的、今世的呢？因为神从天上垂看世人，结果发现没有义人，连一个也没有。没有行善的，一个也没有。神那公义的愤怒天天被人触动。此时此刻，他就正在怒火中烧。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("然而，他却没有立即来毁灭这个世界，他手中那装满愤怒的杯现在却没有倾倒出来，那些得罪他的人现在仍然在岁月静好。他们现在仍然又吃又喝，又娶又嫁，又买又卖，又耕种又盖造。这是因为神现在仍暂时饶恕着这些人，才使他们的性命可以暂时存活。但是，终有一天，在今世过去之后，他那积累的烈怒将会倾泻而出。到那个时候，这些人会向山和岩石说：倒在我们身上吧，把我们藏起来，让我们可以躲避神的愤怒！（启示录6:16）这些人会祈求神说：我情愿挖掉双眼，砍断双腿，也不愿意和你同在，因为你把怒气像汪洋一样倾泻在我身上（马太福音18:8~9）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们这公义层面的饶恕，有部分也是这样的。面对冒犯他的人，神没有现在就把愤怒倾倒出来，神的子民也不要。神在今世暂时饶恕着他们，神的子民也要这样饶恕。神在永恒中必会报复、惩罚，使他的公义得伸张，神的子民要等待、盼望这一天的到来。所以保罗劝我们：“不要自己伸冤，宁可让步，听凭主怒，因为经上记着，主说‘伸冤在我，我必报应’”。（罗马书12:19）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么说神这“公义的饶恕”有部分又是彻底的、永恒的呢？因为从那没有善行的众人中，神凭他的恩典拣选了一部分人成为他的子民，赐给他们圣灵，重生他们，引导他们认罪悔改。神已经把对他们的愤怒倾倒在了他们所依靠的那位救主——拿撒勒人耶稣身上。他为他们的罪死了，三天后复活，还清了他们在神那里的所有罪债。所以对他们的过犯，神已经彻底饶恕、永远不再惩罚了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们这公义层面的饶恕，有部分也是这样的。面对那些有过犯的神的子民，当他们认罪、悔改，神已经彻底赦免了、饶恕了，其他的人有什么资格不去赦免、饶恕，而要追讨到底呢？所以保罗劝我们，若有弟兄犯了罪而忧愁，众人挽回他、甚至责罚他，也就够了，更要赦免他、安慰他，免得他忧愁太过，甚至沉沦了。（哥林多后书2:6）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么说神这“公义的饶恕”又是带着对人的深切期盼呢？因为人得罪了神，神却没有立即施行毁灭，而是给他时间、机会，为叫他能认罪、悔改、信靠他所赐下的救恩。这不是他耽延，乃是他宽容，不愿有一人沉沦，乃愿人人都悔改（彼得后书3:9）。正像他曾经告诉他的仆人以西结：“我断不喜悦恶人死亡，唯喜悦恶人转离所行的道而活”。（以西结书33:11）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们这公义层面的饶恕，也是带着对人回转的深切盼望。这饶恕不是“放下”，而是“放不下”，放不下他的灵魂，不忍看到他沉沦，盼望他认识真道。所以保罗才劝我们：“要用温柔劝诫那抵挡的人，或者神给他们悔改的心，可以明白真道，叫他们这已经被魔鬼任意掳去的，可以醒悟，脱离他的网罗。”（提摩太后书2:26）")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就是圣经中讲的饶恕。有个人层面的，也有公义层面的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在解释了这么多之后，那我们应当如何实际地去饶恕人呢？我将其总结为以下几点：第一，仰望上帝，舍弃自己。仰望神，并将自己全然沉浸于神那无限的恩典与慈爱之中；靠着圣灵的帮助，舍弃自我，摆脱私欲的缠累。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第二，控制怒气，交托于主。无论是出于私欲受挫的愤怒，还是出于公义未彰的义怒，都不要任由怒火驱使你的言行。把你的一切怒气交托给公义的主，相信他必有伸张公义的时候。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第三，怀着盼望，用心行动。带着盼望他与神和好的心，采取行动。你可以是为他祷告，可以是温柔劝诫，甚至可以是施以管教。但怎么行动不是重点，你的心才是。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你这样去做，就是饶恕人，就是把你的恩慈、怜悯给人。你这样去做，正显明你是神的子民。因为唯有神的子民，才会专心仰望神，为了神的缘故舍弃自我；才会与神同心，效法神的样式来对待人。而神也必如主耶稣所言，彻底的、永恒地饶恕你们，把他丰富的恩典，用十足的升斗、连摇带按，上尖下流地倒在你们的怀里（路加福音6:38）。并且你们对人的饶恕越多，也就是你对神的仰望越多、对自我的舍弃越多、与神同心越多，这样，神的祝福临到你也就越发丰盛。这就是路加福音6：38节最后一句话“你们用什么量器量给人，也必用什么量器量给你们”的意思。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这是主耶稣在6:37~38节中，从肯定的方面教导我们，如何去爱那些有过犯的人，也就是我们的打油诗的第二句：只求与主心意同。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("三、正人之前先正己，免得最后两手空")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在第37~38节，耶稣用四了个排比句，分别从否定、肯定两方面教导我们如何去爱那些有过犯之人。从第39节开始，他转换了一种表达方式，开始用“比喻”继续阐述这个主题。这里所说的“比喻”，英文翻译为parable，和作为修辞手法的“比喻”（英文翻译是figure of speech）不是一个意思。例如我们说“他长得像朵花”就是一个修辞手法意义上的比喻。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这里翻译为“比喻”的这个词，是一种文学体裁而非修辞手法，更接近于中文中的“寓言故事”。在接下来的经文中，这种文学体裁只出现在第39~40节。从41节开始，耶稣没有再继续用这种文体，而是重新回到直接陈述的方式，对39~40节的寓言进行总结和解释。当然在这番总结和解释中，他又使用了修辞意义上的比喻。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来看第39~40节，这里实际上他讲了两个场景。一个是两个瞎子的场景，一个是学生和先生的场景。但路加在第39节提到用“比喻”，或者说寓言这个词，用的是单数。也就是说，在这两个场景中，耶稣是在讲同一样的寓言，说同一个道理。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们应该怎么去爱、善待那些有过犯的人？当然是希望通过我们的行动，让他能悔改、回转，离弃罪，归向神，这才是爱他，善待他。此时他就像是一个瞎子需要我们指引，就像是一个学生需要我们来教导、劝诫、帮助。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那如果我们自己都是瞎子，不知道要走向哪里，那么当然我们对他的引领也是偏的。如果我们自己作为先生，才疏学浅，甚至不学无术，那当然也教不出什么好学生了。在这种情况下，反而会成了他悔改、回转、离弃罪、归向神的障碍。也许我们有为他好的动机，但我们自身的状态导致我们未必能做出对他好的事。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，主耶稣在这里告诉我们，爱、善待那些有过犯的人，光有动机不够，光有好心不够，你自己的状态还需要调整好，否则你会阻碍他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这个状态，就是他在37~38节所讲的：莫把自己放高位、只求与主心意同。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("主耶稣告诉我们：在你与这个人的关系中，你不要把自己放在一个高高在上的法官的位置，去论断他、定罪他；而是要把自己放在一个低低在下的仆人的位置，去服侍他、劝勉他、帮助他。但我们呢？我们常常打着劝勉、帮助的旗号，行的却是论断、定罪之事，因为我们在行动之前，没有先去省察自己的心。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("主耶稣告诉我们：在你与这个人的关系中，你不要出于私欲而行事，也不要把怒气倾倒给他；而是要像你们的族长，那位至高者一样，给他怜悯、恩慈、饶恕，殷切盼望他悔改、归正。但我们呢？我们常常是凭感情驱使，随冲动行事，因为我们对自己的认识与神所赐的身份之间是割裂的。神让我们做宇宙的贵族，以神儿女的心肠来对待人，而我们却对这个身份没有认识、没有感觉。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("欲正人，先正己。否则就是瞎子引瞎子，坏先生教坏学生。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在第41~42节他不再用寓言，而是直接阐明这个道理：我们如果要去纠正弟兄的错、帮助他悔改归正，需要先面对自己的罪，自己先悔改、归正。我们把自己放高位、不与主同心，我们就是瞎子，就是坏先生，当然我们自己也就在过犯当中。耶稣说，唯有先解决了自己的罪，才能看得清楚；唯有先看清楚了，才能正确帮助弟兄来悔改、归正。否则，做手术下错了地方，反而会将别人眼睛给弄得更瞎了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我自己就曾是一个失败的例子。我儿子小时候，和许多男孩子一样，会做许多得罪神的事：撒谎、不听从父母、搞小团体排挤弱势同学、只想独占玩具不肯分享，如此种种。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那我在管教他时，有没有不把自己居高位、只求与主心意同、正人之前先正己呢？没有。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("有一次他对我的父母出言不逊，我怒火上涌，当场就伸手打了他耳光；")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("还有一次，他因为用电脑的问题与我反复理论，耗尽了我的耐心，我气极之下轻蔑地说：“这是我的家，你要是有本事，就搬出去自己住，这样你就可以随心所欲了”；")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("也有一回，在一次争执中，他推搡我的妻子，我非常愤怒，但我知道应该控制自己的怒气，于是流着泪向神祷告、求神帮助。但等到愤怒的情绪过去，我看到他，又对他心生怜爱，于是就把这事放下了，没有再按照神的要求去教导他、管教他，让他认识到这件事是错的、得罪神的——弟兄姐妹们，我确实是怜爱他，但不是与神同心地怜爱他，我没有把公义的饶恕给他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你们看到了吗？神把一个男孩子放在我身边，是让我去服侍他、陪伴他成长。但我却对他有很多的论断、定罪；有很多的凭感情驱使，随冲动行事；有很多的不怜悯、不恩慈、不饶恕；他有过错时，我不是以善胜恶，而是以恶报恶。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就叫瞎子领瞎子，这就叫坏先生去教坏学生，这就叫没有去掉自己眼中的梁木就跑去要去掉弟兄眼中的刺了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("对于我这样的人，主耶稣是怎么评价的呢？我们看第42节这句话：你这假冒为善的人！大家知道，假冒为善在新约中是对谁的评价？那些文士和法利赛人！主耶稣在马太福音23：27节说“你们这假冒为善的文士和法利赛人有祸了！因为你们好像粉饰的坟墓，外面好看，里面却装满了死人的骨头和一切的污秽。而当我居高临下，当我不与神同心，当我在正人之前不先正己，那我就是这样的！而这样的人，有祸了！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那弟兄姐妹们，你们呢？你们是这样的人吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("今天这段经文，是关于如何去爱、去善待那些有过犯的人。但大家会发现，核心不是如何对待他们，而是你如何对待自己。你在面对他们时，是不是先调整好了自己，如果没有，那么是非常危险的。雅各书3:1提醒我们，不要多人作师傅，因为晓得这些人会受更重的审判。但圣经又命令我们每个人要彼此劝诫（罗马书15：14），又命令我们每个人要去传主的福音，劝人悔改，所以我们每个人又多多少少必须去面对那些有过犯的人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这意味着你必须调整自己。你必须要把心态摆正，你是仆人，不是法官；你必须操练自己与主同心，仰望神舍弃自我，用公义的饶恕去对待人；你必须不断认罪、悔改、转向神。你必须像保罗所说的那样，攻克己身、叫身服我，免得传福音给别人，自己反被弃绝了（林前9:27）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“莫把自己放高位，只求与主心意同。正人之前先正己，免得到头两手空。”阿门？")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);